   331→// getUntrackedFilesForState returns a list of untracked files using go-git
   332→// Excludes .entire directory
   333→func getUntrackedFilesForState() ([]string, error) {
   334→	repo, err := openRepository()
   335→	if err != nil {
   336→		return nil, err
   337→	}
   338→
   339→	worktree, err := repo.Worktree()
   340→	if err != nil {
   341→		return nil, err
   342→	}
   343→
   344→	status, err := worktree.Status()
   345→	if err != nil {
   346→		return nil, err
   347→	}
   348→
   349→	var untrackedFiles []string
   350→	for file, st := range status {
   351→		if st.Worktree == git.Untracked {
   352→			// Exclude .entire directory
   353→			if !strings.HasPrefix(file, paths.EntireDir+"/") && file != paths.EntireDir {
   354→				untrackedFiles = append(untrackedFiles, file)
   355→			}
   356→		}
   357→	}
   358→
   359→	return untrackedFiles, nil
   360→}
