func TestTransition(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		current     Phase
		event       Event
		ctx         TransitionContext
		wantPhase   Phase
		wantActions []Action
	}{
		// --- IDLE transitions ---
		{
			name:        "IDLE_TurnStart_transitions_to_ACTIVE",
			current:     PhaseIdle,
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_triggers_condense",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_rebase_skips_everything",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_SessionStop_transitions_to_ENDED",
			current:     PhaseIdle,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_SessionStart_is_noop",
			current:     PhaseIdle,
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_TurnEnd_is_noop",
			current:     PhaseIdle,
			event:       EventTurnEnd,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},

		// --- ACTIVE transitions ---
		{
			name:        "ACTIVE_TurnStart_stays_ACTIVE",
			current:     PhaseActive,
			event:       EventTurnStart,
